from __future__ import annotations


PATCH_MARKER = "V6.22 BOQ MULTISHEET V2"


def patch_boq_multisheet(source: str) -> str:
    """Inject Excel-like multi-sheet BOQ import UI into generated V6.22 cost module."""
    if PATCH_MARKER in source:
        return source

    function_anchor = "\ndef render_cost_management(pid: int):\n"
    if function_anchor not in source:
        raise RuntimeError("V6.22 BOQ patch: render_cost_management anchor missing")

    helper = '''\n# V6.22 BOQ MULTISHEET V2 START\nfrom boq_multisheet_v622 import (\n    BOQWorkbookError as _V622BOQWorkbookError,\n    build_summary_excel as _v622_build_boq_summary_excel,\n    parse_boq_workbook as _v622_parse_boq_workbook,\n    save_boq_summary_to_project as _v622_save_boq_summary_to_project,\n)\n\n@st.cache_data(show_spinner=False)\ndef _v622_parse_boq_cached(data: bytes, filename: str):\n    return _v622_parse_boq_workbook(data, filename)\n\n# V6.22 BOQ MULTISHEET V2 END\n'''
    source = source.replace(function_anchor, helper + function_anchor, 1)

    ui_anchor = '''        rows = db.cost_budgets(pid)\n        total_bac = sum(float(r["budget_total"] or 0) for r in rows)\n        st.metric("Tổng ngân sách kế hoạch (BAC)", f"{_vnd(total_bac)} VND")\n'''
    if ui_anchor not in source:
        raise RuntimeError("V6.22 BOQ patch: cost tab anchor missing")

    ui_block = ui_anchor + '''\n        with st.expander("📥 Nhập BOQ Excel nhiều sheet", expanded=not bool(rows)):\n            st.caption(\n                "Giữ cấu trúc workbook theo từng sheet như Excel; tự tách sheet SUM/Phụ lục tổng hợp, "\n                "đọc toàn bộ BOQ chi tiết và không yêu cầu nhập từng mục thủ công."\n            )\n            _boq_file = st.file_uploader(\n                "Chọn workbook BOQ (.xlsx / .xlsm)",\n                type=["xlsx", "xlsm"],\n                key=f"cost_boq_excel_{pid}",\n            )\n            _boq_replace = st.checkbox(\n                "Thay BOQ đã nhập từ Excel trước đây của dự án (không xóa BOQ nhập thủ công)",\n                value=True,\n                key=f"cost_boq_excel_replace_{pid}",\n            )\n            if _boq_file is not None:\n                try:\n                    _boq_result = _v622_parse_boq_cached(_boq_file.getvalue(), _boq_file.name)\n                except _V622BOQWorkbookError as _boq_exc:\n                    st.warning(str(_boq_exc))\n                except Exception as _boq_exc:\n                    st.error(f"Không thể phân tích file BOQ: {_boq_exc}")\n                else:\n                    _book_names = list(_boq_result.get("workbook_sheet_names") or [])\n                    _detail_names = list(_boq_result.get("detected_sheets") or [])\n                    _summary_info = _boq_result.get("summary_sheet") or {}\n                    _summary_name = str(_summary_info.get("sheet") or "")\n\n                    _msg = (\n                        f"Đã đọc {len(_book_names)} sheet hiển thị và nhận diện "\n                        f"{len(_detail_names)} sheet BOQ chi tiết ({int(_boq_result.get('detail_line_count') or 0):,} dòng)."\n                    )\n                    if _summary_name:\n                        _msg += f" Sheet tổng hợp: {_summary_name}."\n                    st.success(_msg)\n\n                    for _boq_warning in _boq_result.get("warnings") or []:\n                        st.info(_boq_warning)\n\n                    _m1, _m2, _m3 = st.columns(3)\n                    _m1.metric(\n                        "Cộng giá trị trước thuế",\n                        f"{_vnd(_boq_result.get('before_tax_total', 0))} VND",\n                    )\n                    _m2.metric(\n                        "Thuế VAT",\n                        f"{_vnd(_boq_result.get('vat_total', 0))} VND",\n                    )\n                    _m3.metric(\n                        "Cộng giá trị sau thuế",\n                        f"{_vnd(_boq_result.get('after_tax_total', 0))} VND",\n                    )\n\n                    st.markdown("##### 📑 Workbook BOQ – hiển thị theo từng sheet như Excel")\n                    _book_data = _boq_result.get("workbook_sheets") or {}\n                    if _book_names:\n                        _sheet_tabs = st.tabs(_book_names)\n                        for _sheet_name, _sheet_tab in zip(_book_names, _sheet_tabs):\n                            with _sheet_tab:\n                                _snap = _book_data.get(_sheet_name) or {}\n                                _sheet_df = pd.DataFrame(\n                                    _snap.get("rows") or [],\n                                    columns=_snap.get("columns") or None,\n                                )\n                                st.caption(\n                                    f"{int(_snap.get('row_count') or 0):,} dòng × "\n                                    f"{int(_snap.get('col_count') or 0):,} cột"\n                                )\n                                if bool(_snap.get("truncated")):\n                                    st.warning("Sheet quá lớn; màn hình xem trước đã được giới hạn để bảo vệ bộ nhớ.")\n                                st.dataframe(\n                                    _sheet_df,\n                                    hide_index=True,\n                                    width="stretch",\n                                    height=540,\n                                )\n\n                    _appendix_rows = list(_summary_info.get("rows") or [])\n                    if _appendix_rows:\n                        st.markdown("##### 📋 Phụ lục tổng hợp giá trị")\n                        _appendix_df = pd.DataFrame(_appendix_rows).rename(columns={\n                            "stt": "STT",\n                            "item": "NỘI DUNG CÔNG VIỆC",\n                            "amount": "TỔNG (VND)",\n                            "note": "GHI CHÚ",\n                        })\n                        _appendix_cols = [c for c in ["STT", "NỘI DUNG CÔNG VIỆC", "TỔNG (VND)", "GHI CHÚ"] if c in _appendix_df.columns]\n                        st.dataframe(\n                            _appendix_df[_appendix_cols],\n                            hide_index=True,\n                            width="stretch",\n                        )\n\n                    _boq_summary = pd.DataFrame(_boq_result.get("summary") or [])\n                    if not _boq_summary.empty:\n                        st.markdown("##### 🧾 Tổng hợp các sheet BOQ chi tiết")\n                        _boq_show = _boq_summary.rename(columns={\n                            "sheet": "Sheet BOQ",\n                            "line_count": "Số dòng chi tiết",\n                            "budget_total": "Giá trị trước thuế (VND)",\n                            "header_row": "Dòng tiêu đề",\n                        })\n                        st.dataframe(\n                            _boq_show[["Sheet BOQ", "Số dòng chi tiết", "Giá trị trước thuế (VND)", "Dòng tiêu đề"]],\n                            hide_index=True,\n                            width="stretch",\n                        )\n\n                    _boq_d1, _boq_d2 = st.columns([1.2, 1.8])\n                    _boq_d1.metric(\n                        "Dòng BOQ sẽ nhập",\n                        f"{int(_boq_result.get('detail_line_count') or 0):,}",\n                    )\n                    _boq_d2.download_button(\n                        "⬇️ Tải Phụ lục tổng hợp giá trị",\n                        data=_v622_build_boq_summary_excel(_boq_result),\n                        file_name=f"Phu_luc_tong_hop_gia_tri_DA_{pid}.xlsx",\n                        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",\n                        key=f"cost_boq_excel_summary_download_{pid}",\n                        width="stretch",\n                    )\n\n                    if st.button(\n                        "💾 Nhập toàn bộ BOQ chi tiết vào dự án",\n                        type="primary",\n                        disabled=not _can_update(),\n                        key=f"cost_boq_excel_save_{pid}",\n                        width="stretch",\n                    ):\n                        try:\n                            with st.spinner("Đang ghi BOQ chi tiết vào cơ sở dữ liệu..."):\n                                _boq_stats = _v622_save_boq_summary_to_project(\n                                    db, pid, _boq_result, replace_existing_excel=_boq_replace\n                                )\n                            st.success(\n                                f"Đã nhập {_boq_stats['inserted']:,} dòng BOQ chi tiết; "\n                                f"giá trị trước thuế {_vnd(_boq_stats['before_tax_total'])} VND; "\n                                f"sau thuế {_vnd(_boq_stats['after_tax_total'])} VND."\n                            )\n                            st.rerun()\n                        except Exception as _boq_exc:\n                            st.error(f"Không thể lưu BOQ vào database: {_boq_exc}")\n'''
    source = source.replace(ui_anchor, ui_block, 1)

    if source.count(PATCH_MARKER) < 2:
        raise RuntimeError("V6.22 BOQ patch marker missing after injection")
    return source
